#!/usr/bin/env bash
# Generate deploy/local/*.env from the committed development keys.
#
# `make prod-local` runs the production compose file on a laptop, and that
# file expects one env file per service -- the same least-privilege split the
# instance uses, where the gateway never sees the console password and
# Grafana never sees the key pepper. On the instance those files are written
# from SSM. Here they are written from the development keys in
# switchyard.toml, which are public on purpose.
#
# The output is git-ignored. It is not secret, but a generated file in a diff
# is noise, and someone will eventually put a real key in one.
set -euo pipefail

cd "$(dirname "$0")/.."
OUT=deploy/local
mkdir -p "$OUT" "$OUT/state"

# These are the development keys committed in switchyard.toml. They are minted
# against the built-in development pepper and are worthless anywhere that sets
# SWITCHYARD_KEY_PEPPER -- which every real deployment does.
ADMIN_KEY="sk_sy_admin_672e27a104b9ede9182f129f4b288395"
ACME_KEY="sk_sy_acme_b6525e6c60405226fc726bdda422dd2f"
GLOBEX_KEY="sk_sy_globex_834d97c4fbd22ebe7a67696345b8693f"
INITECH_KEY="sk_sy_initech_64b4a01257ee3b9d7b2caf98079f8886"

# The gateway gets the pepper and nothing else. Left unset here so the
# development keys above keep working; a real deployment sets it, which is
# precisely what makes those keys worthless off a laptop.
cat > "$OUT/gateway.env" <<ENV
# Generated by scripts/dev-secrets.sh -- do not edit, do not commit.
# SWITCHYARD_KEY_PEPPER is deliberately unset: the committed development keys
# are minted against the built-in default, and setting a pepper here would
# invalidate them.
SWITCHYARD_LOG_LEVEL=INFO
ENV

cat > "$OUT/console.env" <<ENV
# Generated by scripts/dev-secrets.sh -- do not edit, do not commit.
SWITCHYARD_ADMIN_KEY=${ADMIN_KEY}
CONSOLE_DEMO_KEYS={"acme":"${ACME_KEY}","globex":"${GLOBEX_KEY}","initech":"${INITECH_KEY}"}
CONSOLE_PASSWORD=demo
CONSOLE_SESSION_SECRET=local-development-not-a-secret
CONSOLE_GRAFANA_URL=http://localhost:3000
CONSOLE_GRAFANA_INTERNAL_URL=http://grafana:3000
CONSOLE_PUBLIC_API_URL=http://localhost:8000
CONSOLE_DEMO_CONTROLS=true
ENV

cat > "$OUT/grafana.env" <<ENV
# Generated by scripts/dev-secrets.sh -- do not edit, do not commit.
GF_SECURITY_ADMIN_PASSWORD=admin
# Alerting goes nowhere locally. On the instance these come from SSM.
TELEGRAM_BOT_TOKEN=
TELEGRAM_CHAT_ID=
ENV

# Prometheus reads its scrape credential from a file so the key is not baked
# into a config that lives in git.
printf '%s' "${ADMIN_KEY}" > "$OUT/scrape-key"

# A local copy of the production config with the development digests
# substituted for the placeholders. Keeping the production *shape* --
# max_concurrency 12, shallow queues, the same floors -- is the point of
# prod-local: it rehearses the deployed configuration, not a friendlier one.
python3 - "$ADMIN_KEY" "$ACME_KEY" "$GLOBEX_KEY" "$INITECH_KEY" <<'PY'
import sys, pathlib
sys.path.insert(0, "src")
from switchyard.core.auth import hash_key

admin, acme, globex, initech = sys.argv[1:5]
text = pathlib.Path("deploy/switchyard.prod.toml").read_text()
placeholder = '"' + "0" * 64 + '"'

# Order matters: admin first, then the tenants in the order they appear.
for raw in (admin, acme, globex, initech):
    assert placeholder in text, "ran out of placeholders -- has the prod config changed?"
    text = text.replace(placeholder, f'"{hash_key(raw)}"', 1)

assert placeholder not in text, "a placeholder digest was left unreplaced"
text = text.replace(
    "# The digests below are PLACEHOLDERS.",
    "# GENERATED by scripts/dev-secrets.sh from the development keys.\n"
    "# The committed deploy/switchyard.prod.toml has placeholders instead.\n"
    "# Originally:  The digests below are PLACEHOLDERS.")
text = text.replace('state_file = "/var/lib/switchyard/state.json"',
                    'state_file = "/var/lib/switchyard/state.json"')
pathlib.Path("deploy/local/switchyard.toml").write_text(text)
print("wrote deploy/local/switchyard.toml with development digests")
PY

chmod 600 "$OUT"/*.env "$OUT/scrape-key"
echo "wrote $OUT/{gateway,console,grafana}.env and $OUT/scrape-key"
echo
echo "These are DEVELOPMENT credentials, committed on purpose and worthless"
echo "anywhere that sets SWITCHYARD_KEY_PEPPER. Console password: demo"
